pseudocode.ordinary:
output = { linear: (linearAccelerationX, linearAccelerationY),
           angular: angularAcceleration }
if seconds >= pulseSeconds:
  output = { linear: (0, 0), angular: 0 }

velocity = velocity + output.linear * timeStep

rotation = rotation + output.angular * timeStep

position = position + velocity * timeStep
heading = heading + rotation * timeStep
